#include <stdatomic.h>

// Assume GPUInfo is a user-defined type representing GPU information.
typedef struct {
    // Fields representing GPU information.
} GPUInfo;

// Assume merge_gpu_info is a user-defined function that merges two GPUInfo instances.
// Returns 0 on success, non-zero on failure.
int merge_gpu_info(GPUInfo* dest, const GPUInfo* src);

// Assume current_gpu_info is a global atomic variable representing the current GPU information.
// Assume lock is a global atomic variable representing a lock for the GPU information.
atomic<GPUInfo> current_gpu_info;
atomic<int> lock;

void update_gpu_info(const GPUInfo& new_gpu_info) {
    // Try to acquire the lock
    while (atomic_exchange(&lock, 1) == 1) {
        // Wait until the lock is released
    }

    // Create a temporary copy of the current GPU info
    GPUInfo temp_gpu_info = atomic_load(&current_gpu_info);

    // Attempt to merge the new GPU info with the current one
    int merge_result = merge_gpu_info(&temp_gpu_info, &new_gpu_info);

    // If the merge was successful, update the current GPU info
    if (merge_result == 0) {
        atomic_store(&current_gpu_info, temp_gpu_info);
    }

    // Release the lock
    atomic_store(&lock, 0);
}
